import type { Metadata } from "next";
import Link from "next/link";
import { ArrowLeft, ArrowRight, ArrowUpRight } from "lucide-react";
import { notFound } from "next/navigation";
import MirorCommandCenter from "@/components/experience/MirorCommandCenter";
import MirorHomeController from "@/components/home/MirorHomeController";
import MirorProjectStoryEngine, { type ProjectStory } from "@/components/projects/MirorProjectStoryEngine";
import { getProjectBySlug, getRelatedProjects } from "@/data/miror-v4-content";

export function generateStaticParams(){return ["hnss-kuppam-branch-canal-phase-ii","revasa-la-valora"].map((slug)=>({slug}));}
export async function generateMetadata({params}:{params:Promise<{slug:string}>}):Promise<Metadata>{const {slug}=await params;const p=getProjectBySlug(slug);if(!p)return{title:"Project not found | Miror Constructions"};return{title:`${p.title} | Miror Constructions`,description:p.summary};}
function mapProject(p:NonNullable<ReturnType<typeof getProjectBySlug>>):ProjectStory{return{slug:p.slug,title:p.title,subtitle:p.subtitle,category:p.category,location:p.location,region:p.region,status:p.status,publicationPermission:p.publicationPermission,sourceDocument:p.sourceDocument,client:p.client,principalContractor:p.principalContractor,mirorRole:p.mirorRole,summary:p.summary,description:p.description,scope:p.scope,disciplines:p.disciplines,metrics:p.metrics,gallery:p.gallery.map((m)=>({...m,type:"image" as const})),milestones:[{id:`${p.slug}-01`,title:"Project evidence",description:p.description}],relatedSlugs:[],cover:{...p.gallery[0],id:`${p.slug}-cover`,type:"image" as const},film:undefined};}
export default async function ProjectPage({params}:{params:Promise<{slug:string}>}){const {slug}=await params;const p=getProjectBySlug(slug);if(!p)return notFound();const story=mapProject(p);const related=getRelatedProjects(p).map(mapProject);return <MirorCommandCenter route={`/work/${p.slug}`} showFooter><MirorHomeController><main className="bg-[#f4f1ea] text-[#111214]"><div className="mx-auto max-w-[1440px] px-5 pt-[13vh] md:px-8 lg:px-12"><div className="flex items-center justify-between gap-4 border-b border-black/10 pb-5"><Link href="/work" className="inline-flex items-center gap-2 text-[9px] uppercase tracking-[.14em] text-black/35"><ArrowLeft size={13}/> All work</Link><Link href="/contact#contact" className="inline-flex items-center gap-2 text-[9px] uppercase tracking-[.14em] text-black/45">Discuss a scope <ArrowUpRight size={13}/></Link></div></div><MirorProjectStoryEngine project={story} related={related}/><div className="mx-auto max-w-[1440px] px-5 pb-20 md:px-8 lg:px-12"><div className="grid gap-4 md:grid-cols-2"><Link href="/work" className="rounded-[22px] border border-black/10 p-5"><span className="inline-flex items-center gap-2 text-[9px] uppercase tracking-[.13em] text-black/35"><ArrowLeft size={13}/> Portfolio</span><h2 className="mt-5 text-2xl tracking-[-.04em]">Return to all work</h2></Link><Link href="/contact#contact" className="rounded-[22px] bg-[#111214] p-5 text-[#f4f1ea]"><span className="flex items-center justify-between text-[9px] uppercase tracking-[.13em] text-white/40"><span>Next step</span><ArrowRight size={13}/></span><h2 className="mt-5 text-2xl tracking-[-.04em]">Talk to the Miror team</h2></Link></div></div></main></MirorHomeController></MirorCommandCenter>}

